  "tags": [],
  "prompt": "{\n  \"type\": \"编辑类科学信息图海报\",\n  \"style\": \"面向青少年的友好型杂志风格科普信息图，结合手绘物理图解、卡通角色和简洁的编辑排版\",\n  \"topic\": \"原初黑洞、霍金辐射与记忆负担暗物质\",\n  \"canvas\": {\n    \"orientation\": \"纵向\",\n    \"background\": \"暖色调奶油纸纹理，带有细微颗粒感\",\n    \"border\": \"页面四周带有纤细的柔和灰色矩形边框\"\n  },\n  \"headline\": {\n    \"title\": \"拒绝消亡的黑洞\",\n    \"subtitle\": \"一个诞生于宇宙最初一秒的微小黑洞，以及可能让它伪装成暗物质的奇特新物理学。\",\n    \"credit\": \"Thoss, Lopez-Honorez, Kühnel & Hufnagel\"\n  },\n  \"layout\": {\n    \"sections\": [\n      {\n        \"title\": \"闪电般的诞生\",\n        \"position\": \"左上\",\n        \"count\": 4,\n        \"labels\": [\n          \"早期宇宙旋转诞生示意图\",\n          \"比盐粒还小但比山还重的原初黑洞\",\n          \"大爆炸后 10^-30 秒的时钟图标\",\n          \"温度计图标\"\n        ]\n      },\n      {\n        \"title\": \"普通黑洞的蒸发\",\n        \"position\": \"右上\",\n        \"count\": 4,\n        \"labels\": [\n          \"从左至右三个黑洞缩小阶段\",\n          \"每个阶段周围的粒子外溢波浪线\",\n          \"斯蒂芬·霍金的解释段落\",\n          \"贴纸引言：\\\"黑洞并非那么黑\\\" — S. Hawking, 1974\"\n        ]\n      },\n      {\n        \"title\": \"情节反转：记忆负担\",\n        \"position\": \"中中\",\n        \"count\": 4,\n        \"labels\": [\n          \"背着标有 MEMORY 背包的悲伤超载卡通黑洞\",\n          \"关于因信息过载而无法完成蒸发的对话气泡\",\n          \"公式：正常速度 ÷ (大量信息)^k = 爬行速度\",\n          \"关于 Gia Dvali 2018 年提议的括号注释\"\n        ]\n      },\n      {\n        \"title\": \"两种幽灵粒子\",\n        \"position\": \"中下\",\n        \"count\": 5,\n        \"labels\": [\n          \"左侧快速移动的粒子\",\n          \"右侧缓慢温暖的粒子角色\",\n          \"从大爆炸到今天的演化时间轴\",\n          \"快速且寒冷云朵标签\",\n          \"缓慢且温暖云朵标签\"\n        ]\n      },\n      {\n        \"title\": \"我们如何捕捉它们：莱曼-α 森林\",\n        \"position\": \"左下\",\n        \"count\": 4,\n        \"labels\": [\n          \"关于古老星系穿过氢云的段落\",\n          \"尖刺状的吸收森林景观图\",\n          \"手写注释：森林告诉我们：我们会发现的。\",\n          \"从我们到遥远类星体的轴线概念\"\n        ]\n      },\n      {\n        \"title\": \"这篇论文说明了什么？\",\n        \"position\": \"右下\",\n        \"count\": 1,\n        \"labels\": [\n          \"圆角矩形总结框\"\n        ]\n      }\n    ],\n    \"count\": 6\n  },\n  \"visuals\": {\n    \"color_palette\": [\n      \"暖米色\",\n      \"深海军蓝\",\n      \"铁锈橙\",\n      \"灰青色\",\n      \"柔棕色\",\n      \"柔和灰\"\n    ],\n    \"illustration_notes\": \"扁平矢量形状，带有略显粗糙的轮廓、柔和阴影、圆润形态，既俏皮又具备科学严谨性\",\n    \"typography\": \"标题使用大号衬线全大写字母，章节标题使用粗体无衬线字体，正文紧凑易读，偶尔点缀手写体文字\"\n  },\n  \"objects\": {\n    \"count\": 15,\n    \"items\": [\n      \"1 个全页边框\",\n      \"1 个标题块\",\n      \"1 个早期宇宙旋转图\",\n      \"1 个带有标注的微小原初黑洞点\",\n      \"1 个时钟图标\",\n      \"1 个温度计图标\",\n      \"3 个黑洞蒸发图解\",\n      \"1 个霍金引言贴纸徽章\",\n      \"1 个背着背包的卡通黑洞角色\",\n      \"1 个对话气泡\",\n      \"1 个公式块\",\n      \"2 个云朵标签\",\n      \"1 个左下角光谱森林插图\"\n    ]\n  },\n  \"text_blocks\": {\n    \"count\": 9,\n    \"items\": [\n      \"标题\",\n      \"副标题\",\n      \"作者署名\",\n      \"闪电般的诞生正文\",\n      \"普通黑洞蒸发正文\",\n      \"记忆负担解释段落\",\n      \"幽灵粒子说明文字\",\n      \"莱曼-α 森林解释\",\n      \"最终结论总结\"\n    ]\n  },\n  \"composition\": \"布局紧凑但易读的单页说明图，包含多个插图标注，具有清晰的从左至右、从上至下的阅读流向，设计旨在成为可分享的社交媒体科学海报，让青少年也能轻松理解深奥的物理学论文\"\n}",
